<section class="card"><?php if($mentor['avatar_asset_id']): ?><img class="portrait" src="<?= $this->h($this->url('/content/asset?id='.$mentor['avatar_asset_id'])) ?>" width="96" height="96" alt="عکس <?= $this->h($mentor['display_name']) ?>"><?php endif; ?><span class="eyebrow">صاحب تجربه عملی</span><h1><?= $this->h($mentor['display_name']) ?></h1><h2><?= $this->h($mentor['headline']) ?></h2><p class="prose"><?= nl2br($this->h($mentor['bio'])) ?></p><div class="row"><?php foreach($terms as $t): ?><span class="badge"><?= $this->h($t['title']) ?></span><?php endforeach; ?></div><div class="notice section"><strong>گفت‌وگو با این صاحب تجربه</strong><p><?= $mentor['acceptance_paused']?'مرشد فعلاً پذیرش را متوقف کرده است. ':'' ?><?= $mentor['access_scope']==='organization'?'مشاوره ویژه اعضای سازمان مشترک است. ':'' ?>مشاوره رایگان است. رزرو عمومی فعلاً بسته است.</p></div></section>
<section class="card section"><h2>برنامه واقعی مرشد</h2><form method="get"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/slots"><?php endif; ?><input type="hidden" name="mentor_id" value="<?= $this->h($mentor['user_id']) ?>"><label for="slot-date">تاریخ میلادی، به وقت تهران</label><input id="slot-date" type="date" name="date" required><button>مشاهده زمان‌ها</button></form></section>
<h2>تجربه‌های منتشرشده</h2><div class="grid2"><?php foreach($experiences as $e): ?><article class="card"><h3><?= $this->h($e['title']) ?></h3><a href="<?= $this->h($this->url('/experience?id='.$e['id'])) ?>">مطالعه تجربه</a></article><?php endforeach; ?></div><?php if(!$experiences): ?><p>هنوز تجربه منتشرشده‌ای ندارد.</p><?php endif; ?>
